CREATE FUNCTION public_proposal_decisions(cid uuid) RETURNS TABLE(proposal_id uuid, public_reason text) LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT d.proposal_id,d.public_reason FROM decisions d JOIN proposals p ON p.id=d.proposal_id WHERE d.campaign_id=cid AND aar_role(cid) IS NOT NULL AND p.visibility='PARTY' AND p.submitted_by=nullif(current_setting('app.user_id',true),'')::uuid $$;
DROP POLICY characters_access ON characters;
CREATE POLICY characters_access ON characters FOR SELECT USING(aar_role(campaign_id) IS NOT NULL);
CREATE POLICY characters_insert ON characters FOR INSERT WITH CHECK(aar_role(campaign_id)='DM');
CREATE POLICY characters_update ON characters FOR UPDATE USING(aar_role(campaign_id)='DM') WITH CHECK(aar_role(campaign_id)='DM');
