CREATE POLICY proposals_withdraw ON proposals FOR UPDATE USING(submitted_by=nullif(current_setting('app.user_id',true),'')::uuid AND state IN ('PENDING_DM','NEEDS_CLARIFICATION')) WITH CHECK(state='WITHDRAWN' AND submitted_by=nullif(current_setting('app.user_id',true),'')::uuid);
